<?php include APPPATH.'Views/layouts/partials/studio_icons.php'; ?>
<section class="form-section"><header><h2><?= esc(lang('UI.settingsChannels')) ?></h2></header><?php if(!empty($is_global)): ?><table class="studio-grid" data-grid-widths="40,20,20,20"><thead><tr><?php foreach(['TenantMisc.clinic','TenantMisc.email','TenantMisc.sms','TenantMisc.whatsapp'] as $key): ?><th scope="col"><?= esc(lang($key)) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($clinics??[] as $registeredClinic): ?><tr><td><?= esc($registeredClinic['name']) ?></td><?php foreach(['email','sms','whatsapp'] as $type):$channel=null;foreach($registeredClinic['channels'] as $ch)if($ch['channel_type']===$type){$channel=$ch;break;}$enabled=$channel&&!empty($channel['enabled_by_superadmin']); ?><td><button type="button" class="button secondary" data-channel-toggle data-clinic-id="<?= (int)$registeredClinic['id'] ?>" data-channel-type="<?= $type ?>" data-enabled="<?= $enabled?'0':'1' ?>"><?= esc(lang($enabled?'UserRole.deactivate':'UserRole.activate')) ?></button></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table><?php else: ?><div class="settings-channel-list"><?php foreach($channels??[] as $channel):$type=$channel['channel_type'];$locked=empty($channel['enabled_by_superadmin']); ?><article class="settings-channel"><div class="settings-channel-icon"><?= $studioIcon($type==='email'?'message':($type==='sms'?'phone':'message')) ?></div><div><h3><?= esc(lang('TenantMisc.'.$type)) ?></h3><p class="<?= $locked?'settings-danger':'settings-success' ?>"><?= esc(lang($locked?'TenantMisc.disabledUpper':'TenantMisc.activeUpper')) ?></p></div><a class="button secondary" href="<?= base_url('settings?tab=communications&subtab='.$type) ?>"><?= esc(lang('TenantMisc.configureUpper')) ?></a></article><?php endforeach; ?></div><?php endif; ?></section>
